        FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='academic_year_removals'),''))) = 'InnoDB || year_label:varchar(9):NO:~:utf8mb4:,removed_by_user_id:int(11):YES:NULL:-:,removed_at:datetime(6):NO:current_timestamp(6):-: || PRIMARY:0:1:year_label,academic_year_removal_actor_fk:1:1:removed_by_user_id || academic_year_removal_actor_fk:removed_by_user_id:users:id:RESTRICT:SET NULL,academic_year_removal_year_fk:year_label:academic_years:year_label:RESTRICT:RESTRICT || '
    AND (SELECT TABLE_COLLATION FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='academic_year_removals') = @prism_collation);
SET @prism_sql := IF(@prism_tables = @prism_expect16 AND @prism_structure_ok, 'DO 0', 'SELECT `PRISM ABORT: created tables do not match the reviewed contract - version NOT stamped - run PRISM_SCHEMA_16_VERIFY.sql then PRISM_SCHEMA_16_ROLLBACK.sql`');
PREPARE prism_step FROM @prism_sql;
EXECUTE prism_step;
DEALLOCATE PREPARE prism_step;

-- Seed policy rows and stamp the version in one transaction. Student assignments are never changed.
START TRANSACTION;
INSERT IGNORE INTO academic_years(year_label,historical)
    SELECT DISTINCT academic_year,1 FROM students
    WHERE academic_year IS NOT NULL AND TRIM(academic_year)<>'' AND CHAR_LENGTH(academic_year)<=9;
INSERT IGNORE INTO academic_year_settings(year_label)
    SELECT year_label FROM academic_years
    WHERE year_label REGEXP '^[1-9][0-9]{3}-[1-9][0-9]{3}$'
    AND CAST(RIGHT(year_label,4) AS UNSIGNED)=CAST(LEFT(year_label,4) AS UNSIGNED)+1;
UPDATE schema_meta SET v='16' WHERE k='schema_version' AND v='15';
SET @prism_stamped := ROW_COUNT();
INSERT INTO schema_meta(k,v) VALUES ('prism_settings_v1','1');
SET @prism_sql := IF(@prism_stamped = 1, 'DO 0', 'SELECT `PRISM ABORT: version stamp failed - the transaction is abandoned and rolls back on disconnect`');
PREPARE prism_step FROM @prism_sql;
EXECUTE prism_step;
DEALLOCATE PREPARE prism_step;
COMMIT;
DO RELEASE_LOCK('prism_migrate');
SELECT 'result' AS check_name, 'MIGRATED_TO_16 - now run PRISM_SCHEMA_16_VERIFY.sql' AS value
UNION ALL SELECT 'academic_year_settings rows', (SELECT COUNT(*) FROM academic_year_settings)
UNION ALL SELECT 'collation', @prism_collation;
